CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, email text NOT NULL, role text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,email));
CREATE TABLE courses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, name text NOT NULL);
CREATE TABLE assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES courses, name text NOT NULL, rubric_id uuid, due_at timestamptz);
CREATE TABLE rubrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, name text NOT NULL, created_by uuid REFERENCES users);
CREATE TABLE rubric_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rubric_id uuid NOT NULL REFERENCES rubrics, version int NOT NULL, config jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(rubric_id,version));
CREATE TABLE rubric_criteria(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rubric_version_id uuid NOT NULL REFERENCES rubric_versions, criterion_key text NOT NULL, name text NOT NULL, weight numeric(6,3) NOT NULL CHECK(weight > 0 AND weight <= 100), max_score numeric NOT NULL DEFAULT 100, UNIQUE(rubric_version_id,criterion_key));
CREATE TABLE submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, student_id uuid NOT NULL REFERENCES users, assignment_id uuid NOT NULL REFERENCES assignments, status text NOT NULL, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX submissions_course_created_idx ON submissions(assignment_id,created_at DESC);
CREATE TABLE submission_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions, object_key text NOT NULL UNIQUE, sha256 char(64) NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>=0), media_type text, scan_status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evaluation_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions, rubric_version_id uuid NOT NULL REFERENCES rubric_versions, status text NOT NULL, idempotency_key text NOT NULL, evaluator_version text NOT NULL, prompt_version text NOT NULL, model_id text, attempt_count int NOT NULL DEFAULT 0, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(submission_id,idempotency_key));
CREATE INDEX evaluation_queue_idx ON evaluation_jobs(status,created_at);
CREATE TABLE evaluation_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES evaluation_jobs, attempt_no int NOT NULL, started_at timestamptz NOT NULL, ended_at timestamptz, outcome text, error_code text, UNIQUE(job_id,attempt_no));
CREATE TABLE evaluation_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL UNIQUE REFERENCES evaluation_jobs, overall_score numeric(6,2) NOT NULL, provenance jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE criterion_scores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), result_id uuid NOT NULL REFERENCES evaluation_results, criterion_key text NOT NULL, score numeric(6,2) NOT NULL, weighted_score numeric(6,2) NOT NULL, evidence jsonb NOT NULL, confidence numeric(4,3), UNIQUE(result_id,criterion_key));
CREATE TABLE human_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES evaluation_jobs, reviewer_id uuid NOT NULL REFERENCES users, decision text NOT NULL, comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evaluation_events(id bigserial PRIMARY KEY, job_id uuid NOT NULL REFERENCES evaluation_jobs, event_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_records(tenant_id uuid NOT NULL, key text NOT NULL, request_hash char(64) NOT NULL, response jsonb, expires_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,key));
CREATE TABLE outbox_events(id bigserial PRIMARY KEY, aggregate_id uuid NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
